<template><ElConfigProvider namespace="kel"><section class="native-files"><header><small>NAMESPACE FILES</small><span>{{paths.length}} files</span><i/><KsButton size="small" :disabled="!canEdit||saveBusy" @click="newOpen=true">新增脚本</KsButton><KsButton size="small" :disabled="!canEdit||saveBusy" @click="importOpen=true">导入</KsButton></header><p v-if="error" role="alert" class="error">{{error}}</p><div class="body"><aside><KsInput v-model="search" placeholder="搜索脚本和文件"/><button v-for="file in visible" :key="file.path" :class="{active:file.path===active}" :disabled="readBusy||saveBusy" @click="emit('open',file.path)"><CodeTags :size="16"/><span>{{file.path.replace(/^\//,'')}}</span><b v-if="file.dirty" title="未保存">●</b></button><p v-if="loading">加载文件…</p><p v-else-if="!visible.length">没有匹配的文件</p><small>{{isNew?'未保存 Flow · 文件为本地草稿':'当前项目 Namespace'}}</small></aside><main v-if="current&&!readBusy"><div class="filebar"><code>{{active}}</code><small>{{dirty?'● 未保存':'✓ 已保存'}} · {{current.revision?'rev '+current.revision:'本地草稿'}}</small><i/><KsButton size="small" :disabled="saveBusy||isNew||!current.revision" @click="emit('reload')">重新加载</KsButton><KsButton size="small" @click="emit('download')">下载</KsButton><KsButton size="small" :disabled="!canEdit||!dirty||saveBusy||isNew||historical" :loading="saveBusy" @click="emit('save')">保存版本</KsButton><KsButton v-if="hasUse" size="small" type="primary" :disabled="!canUse" @click="useTarget=useTargets.some(t=>t.id===preferredTarget)?preferredTarget!:'new';useOpen=true">在 Flow 中使用</KsButton></div><NativeCodeEditor :source="current.content" :path="active" :language="language" :theme="theme" :readOnly="!canEdit||saveBusy||historical" @change="v=>emit('edit',v)" @save="emit('save')"/><footer><span>{{language}} · UTF-8 · {{current.content.split('\n').length}} 行</span><i/><span>{{historical?'正在查看任务绑定的历史版本；重新加载可切换至最新版':isNew?'先保存 Flow，再保存文件版本；当前草稿随 Flow 保留':!canEdit?'只读：没有编辑权限':'Ctrl / ⌘ + S 保存脚本'}}</span><details v-if="versions.length"><summary>历史（{{versions.length}}）</summary><a v-for="v in versions" :key="v.id" :href="v.url" download>rev {{v.revision}} · {{v.created_at}} · {{v.size}} B</a></details></footer></main><div v-else class="empty">{{readBusy?'正在读取文件…':'新增或导入脚本开始编辑'}}</div></div>
<KsDialog v-model="newOpen" title="新增脚本" width="510px" :teleported="false" :appendToBody="false"><div class="form"><label>语言<select v-model="kind" @change="newPath='scripts/new_script.'+(kind==='python'?'py':'sh')"><option value="bash">Shell Script</option><option value="python">Python Script</option></select></label><label>文件路径<KsInput v-model="newPath" placeholder="scripts/check_gpu.py"/></label><p v-if="error" class="error">{{error}}</p><KsButton :disabled="!canEdit||!newPath.trim()" type="primary" @click="emit('create',newPath,kind)">创建并编辑</KsButton><KsButton @click="newOpen=false">取消</KsButton></div></KsDialog>
<KsDialog v-model="importOpen" title="导入脚本文件" width="510px" :teleported="false" :appendToBody="false"><div class="form"><label>目标目录<KsInput v-model="folder" placeholder="scripts"/></label><input ref="input" type="file" multiple aria-label="选择脚本文件" @change="emit('stage',($event.target as HTMLInputElement).files)"/><div class="import-candidates"><label v-for="(file,index) in pendingImports" :key="index"><span>{{file.name}} · {{file.size}} bytes</span><KsInput v-model="pendingNames[index]" :aria-label="'导入文件名 '+(index+1)"/></label></div><p>支持不超过 1 MiB 的 UTF-8 文本；确认前只预览，重名文件不会被覆盖。</p><KsButton type="primary" :disabled="!pendingImports.length||!canEdit" @click="emit('import',pendingNames,folder)">导入并编辑</KsButton><KsButton @click="importOpen=false;emit('clearImports')">取消</KsButton><p v-if="error" class="error">{{error}}</p></div></KsDialog>
<KsDialog v-model="useOpen" title="在 Flow 中使用" width="510px" :teleported="false" :appendToBody="false"><div class="form"><code>{{active}} · rev {{current?.revision}}</code><label>引用方式<select v-model="useMode" aria-label="脚本引用方式"><option value="namespace">Namespace 文件引用（固定版本）</option><option value="inline">内联脚本快照</option></select></label><label>目标任务<select v-model="useTarget" aria-label="使用脚本的目标任务"><option value="new">新增脚本任务</option><option v-for="task in useTargets" :key="task.id" :value="task.id">替换 {{task.label}}</option></select></label><p>{{useMode==='namespace'?'引用当前已保存文件版本，来源和内容随 Flow 修订冻结；文件后续更新需明确重新关联。':'复制已保存内容为可独立编辑的内联脚本，并保留来源记录。'}} 保存 Flow 后生效，仍走设备预检和审批。</p><KsButton type="primary" :disabled="!canUse||(useTarget!=='new'&&!useTargets.some(t=>t.id===useTarget))" @click="emit('use',useTarget,useMode);useOpen=false">{{useLabel||'载入所选任务脚本'}}</KsButton><KsButton @click="useOpen=false">取消</KsButton></div></KsDialog></section></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';import CodeTags from 'vue-material-design-icons/CodeTags.vue';import NativeCodeEditor from './NativeCodeEditor.vue';
const props=defineProps<{pendingImports:{name:string;size:number}[];paths:{path:string;dirty:boolean}[];active:string;current?:{content:string;revision:number};historical:boolean;dirty:boolean;versions:any[];canEdit:boolean;isNew:boolean;loading:boolean;readBusy:boolean;saveBusy:boolean;error:string;hasUse:boolean;canUse:boolean;useTargets:{id:string;label:string}[];preferredTarget?:string;useLabel?:string;intent?:{action:string;nonce:number}}>(),emit=defineEmits(['open','create','stage','import','clearImports','edit','save','reload','download','use','intentHandled']);
const pendingNames=ref<string[]>([]);watch(()=>props.pendingImports,files=>pendingNames.value=files.map(file=>file.name),{immediate:true});
const search=ref(''),newOpen=ref(false),importOpen=ref(false),useOpen=ref(false),useTarget=ref('new'),useMode=ref<'namespace'|'inline'>('namespace'),kind=ref('bash'),newPath=ref('scripts/new_script.sh'),folder=ref('scripts'),input=ref<HTMLInputElement|null>(null),theme=ref<'light'|'dark'>('dark');
const visible=computed(()=>props.paths.filter(p=>p.path.toLowerCase().includes(search.value.toLowerCase()))),language=computed(()=>props.active.endsWith('.py')?'python':/\.(sh|bash)$/i.test(props.active)?'shell':'plaintext');
watch(()=>props.active,()=>{if(!props.error){newOpen.value=false;importOpen.value=false}if(input.value)input.value.value=''});watch(()=>props.intent?.nonce,()=>{if(props.intent?.action==='new')newOpen.value=true;else if(props.intent?.action==='import')importOpen.value=true;if(props.intent&&['new','import'].includes(props.intent.action))emit('intentHandled')},{immediate:true});
const sync=()=>{theme.value=document.documentElement.classList.contains('ia-dark')||document.documentElement.classList.contains('dark')?'dark':'light'},observer=new MutationObserver(sync);onMounted(()=>{sync();observer.observe(document.documentElement,{attributes:true,attributeFilter:['class']})});onBeforeUnmount(()=>observer.disconnect());
</script>
<style scoped>
.native-files{height:100%;font:12px var(--ks-font-family-sans);color:var(--ks-text-primary);display:flex;flex-direction:column;min-height:490px}.native-files>header,.filebar,footer{display:flex;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid var(--ks-border-default)}header small{font-size:9px;letter-spacing:.08em;color:var(--ks-text-secondary)}i{flex:1}.body{display:grid;grid-template-columns:180px minmax(0,1fr);flex:1;min-height:0}aside{padding:12px;background:var(--ks-bg-base);border-right:1px solid var(--ks-border-default);overflow:auto}aside>button{display:flex;gap:7px;align-items:center;width:100%;padding:10px 6px;text-align:left;border:0;background:transparent;color:inherit;font-size:11px;border-radius:4px}aside>button span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}aside>button.active{background:var(--ks-bg-surface);color:var(--ks-text-link)}aside b{margin-left:auto;color:var(--ks-text-link);font-size:8px}aside>small{display:block;margin-top:24px;font-size:10px;color:var(--ks-text-secondary)}main{min-width:0;display:flex;flex-direction:column;background:var(--ks-bg-surface)}.filebar{flex-wrap:wrap}.filebar code{font-size:11px}.filebar small,footer{font-size:10px;color:var(--ks-text-secondary)}main :deep(.native-code-editor){flex:1;min-height:340px;height:100%}footer{border-top:1px solid var(--ks-border-default);border-bottom:0;flex-wrap:wrap}footer a{display:block;padding:4px}.empty{display:grid;place-items:center;color:var(--ks-text-secondary)}.form{display:grid;gap:15px;font-size:12px}.form label{display:block}.form label>.kel-input,.form select{margin-top:7px}.form select{width:100%;padding:8px;border:1px solid var(--ks-border-default);border-radius:4px;background:var(--ks-bg-input);color:inherit}.form p{line-height:1.6;color:var(--ks-text-secondary)}.error{padding:8px;color:var(--ks-text-error)!important}.muted{color:var(--ks-text-secondary)}
</style>

<style scoped>.native-files .body>main{padding:0;margin:0;max-width:none;align-self:stretch;width:100%}</style>

<style scoped>.import-candidates{display:grid;gap:12px}.import-candidates label{display:grid;grid-template-columns:1fr 200px;align-items:center;gap:12px}.import-candidates span{font-size:11px;color:var(--ks-text-secondary)}</style>
